55	const PROCESSING_FEE = 5;
56	const BASE_PREMIUMS: Record<string, number> = {
57	  sword: 100,
58	  amulet: 60,
59	  staff: 80,
60	  potion: 40,
61	  rune: 25,
62	  moonstone: 25,
63	};
64	
65	const BLOCK_SIZE = 3;
66	const BLOCK_PREMIUM = 60;
67	
68	const isBlock = (sameTypeItems: Item[]): boolean =>
69	  sameTypeItems.length === BLOCK_SIZE;
70	
71	const basePremiumOfItem = (item: Item): number => BASE_PREMIUMS[item.type];
72	
73	const sumOfItemPremiums = (items: Item[]): number =>
74	  items.reduce((sum, item) => sum + basePremiumOfItem(item), 0);
75	
76	const groupByType = (items: Item[]): Item[][] =>
77	  Object.values(
78	    items.reduce<Record<string, Item[]>>((groups, item) => {
79	      groups[item.type] = [...(groups[item.type] ?? []), item];
80	      return groups;
81	    }, {}),
82	  );
83	
84	const basePremiumOfGroup = (items: Item[]): number =>
85	  isBlock(items) ? BLOCK_PREMIUM : sumOfItemPremiums(items);
86	
87	const policyBasePremium = (items: Item[]): number =>
88	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
89	
90	const CURSED_SURCHARGE_RATE = 0.5;
91	
92	const surchargeOfItem = (item: Item): number =>
93	  item.cursed ? basePremiumOfItem(item) * CURSED_SURCHARGE_RATE : 0;
94	
95	const sumOfItemSurcharges = (items: Item[]): number =>
96	  items.reduce((sum, item) => sum + surchargeOfItem(item), 0);
97	
98	const quote = (items: Item[]): QuoteResult => ({
99	  premium:
100	    PROCESSING_FEE + policyBasePremium(items) + sumOfItemSurcharges(items),
101	});
102	
103	export const runScenario = (scenario: Scenario): ScenarioResult => {
104	  const firstStep = scenario.steps[0] as QuoteStep;
105	  return { results: [quote(firstStep.items)] };
106	};
