input.new_string:
const CURSED_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;

const surchargeOfItem = (item: Item): number =>
  item.cursed
    ? basePremiumOfItem(item) * CURSED_SURCHARGE_RATE
    : basePremiumOfItem(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE;

const surchargeOfItem = (item: Item): number => {
  if (item.cursed) return basePremiumOfItem(item) * CURSED_SURCHARGE_RATE;
  if (item.enchantment)
    return basePremiumOfItem(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE;
  return 0;
};
